"""Peer groups, exclusions, conditional frames and missing observations."""
from _draft_helpers import topic

S = """
CREATE TABLE reading(id INTEGER PRIMARY KEY,sensor TEXT,value INTEGER,weight INTEGER,reset INTEGER);
INSERT INTO reading VALUES(1,'A',10,1,1),(2,'A',10,2,0),(3,'A',20,1,0),
 (4,'A',40,1,1),(5,'B',5,1,1),(6,'B',15,3,0);
CREATE TABLE observation(t INTEGER PRIMARY KEY,v TEXT);
INSERT INTO observation VALUES(1,NULL),(2,'red'),(3,NULL),(4,'blue'),(5,NULL);
"""
def T(n,slug,title,concepts,explain,q,out,p,a,b):
    return topic(n,slug,title,"window_details",concepts,explain,S,q,out,p,a,b)

LESSONS = [
 T(247,"groups-frame","GROUPS 按同值组移动窗口",["GROUPS","peer","窗口组"],
   "GROUPS 1 PRECEDING 取当前排序同值组和前一同值组，不是前一物理行。A 的两个 10 同属一组，二者结果都是 20；20 的窗口含两个 10 和自己，合计 40；40 的窗口含 20 与 40，合计 60。",
   "SELECT id,sum(value) OVER(PARTITION BY sensor ORDER BY value GROUPS BETWEEN 1 PRECEDING AND CURRENT ROW) FROM reading ORDER BY id;","1|20\n2|20\n3|40\n4|60\n5|5\n6|20",
   ["增加唯一 id 到窗口排序会拆散同值 peer。","GROUPS 的偏移量统计同值组数，不是数值距离。"],
   ("用 GROUPS 只取当前同值组的行数。","CURRENT ROW 到 CURRENT ROW。","SELECT id,count(*) OVER(PARTITION BY sensor ORDER BY value GROUPS BETWEEN CURRENT ROW AND CURRENT ROW) FROM reading ORDER BY id;","1|2\n2|2\n3|1\n4|1\n5|1\n6|1"),
   ("输出 A 当前组与后一组的金额和。","GROUPS CURRENT ROW 到 1 FOLLOWING。","SELECT id,sum(value) OVER(ORDER BY value GROUPS BETWEEN CURRENT ROW AND 1 FOLLOWING) FROM reading WHERE sensor='A' ORDER BY id;","1|40\n2|40\n3|60\n4|40")),
 T(248,"exclude-current-peer-comparison","排除当前行计算其他观测总量",["EXCLUDE CURRENT ROW","同组比较","窗口排除"],
   "完整分区窗口排除当前物理行后，A 总量 80 分别减去当前值，得到 70、70、60、40；B 得到 15、5。相比用总量相减，显式 EXCLUDE 也适用于 AVG、COUNT 等无法简单相减的聚合。",
   "SELECT id,sum(value) OVER(PARTITION BY sensor ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING EXCLUDE CURRENT ROW) FROM reading ORDER BY id;","1|70\n2|70\n3|60\n4|40\n5|15\n6|5",
   ["排除后若窗口为空，SUM 为 NULL。","EXCLUDE CURRENT ROW 只排当前物理行，保留同值其他行。"],
   ("计算 A 每行之外的其他行数。","COUNT 使用同一排除规则。","SELECT id,count(*) OVER(ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING EXCLUDE CURRENT ROW) FROM reading WHERE sensor='A' ORDER BY id;","1|3\n2|3\n3|3\n4|3"),
   ("输出 B 每行之外的平均值。","B 只有两行，所以平均值是另一行。","SELECT id,avg(value) OVER(ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING EXCLUDE CURRENT ROW) FROM reading WHERE sensor='B' ORDER BY id;","5|15.0\n6|5.0")),
 T(249,"exclude-peer-group","排除整组同值观测进行基线比较",["EXCLUDE GROUP","peer 排除","基线"],
   "EXCLUDE GROUP 会排除当前值所属的全部 peer，即使帧类型为 ROWS。A 两个 10 都被排除后基线总量为 60；20 的基线也是 60，40 的基线为 40。它适用于避免同值批次对比较基线自我影响。",
   "SELECT id,sum(value) OVER(PARTITION BY sensor ORDER BY value ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING EXCLUDE GROUP) FROM reading ORDER BY id;","1|60\n2|60\n3|60\n4|40\n5|15\n6|5",
   ["peer 由窗口 ORDER BY 决定，不是按值列名称自动决定。","没有 ORDER BY 时整个分区可能都是同一 peer 组。"],
   ("A 排除当前同值组后还剩多少行。","COUNT 配合 EXCLUDE GROUP。","SELECT id,count(*) OVER(ORDER BY value ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING EXCLUDE GROUP) FROM reading WHERE sensor='A' ORDER BY id;","1|2\n2|2\n3|3\n4|3"),
   ("仅统计与 A 的 10 值组不同的总量。","普通 WHERE 作为结果交叉核对。","SELECT sum(value) FROM reading WHERE sensor='A' AND value<>10;","60")),
 T(250,"exclude-ties","EXCLUDE TIES 保留自己排除其他并列行",["EXCLUDE TIES","RANGE","累计同值"],
   "累计 RANGE 帧默认含全部当前 peer，EXCLUDE TIES 保留自己但排除其他同值行。两个 10 因而各看到 10，而不是 20；20 看到 40，40 看到 80。它与排除整个 GROUP 的区别在于是否保留当前物理行。",
   "SELECT id,sum(value) OVER(PARTITION BY sensor ORDER BY value RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW EXCLUDE TIES) FROM reading ORDER BY id;","1|10\n2|10\n3|40\n4|80\n5|5\n6|20",
   ["EXCLUDE TIES 不会排除当前行。","窗口排序增加 id 后不再有同值 peer。"],
   ("比较 A 默认累计 RANGE 结果。","不写 EXCLUDE 的同值行共同计入。","SELECT id,sum(value) OVER(ORDER BY value RANGE UNBOUNDED PRECEDING) FROM reading WHERE sensor='A' ORDER BY id;","1|20\n2|20\n3|40\n4|80"),
   ("求 A 的第一组排除其他并列行后平均值。","平均值仍为 10。","SELECT id,avg(value) OVER(ORDER BY value RANGE UNBOUNDED PRECEDING EXCLUDE TIES) FROM reading WHERE sensor='A' AND value=10 ORDER BY id;","1|10.0\n2|10.0")),
 T(251,"filtered-window-aggregate","过滤聚合贡献而保留全部明细行",["FILTER OVER","条件窗口","明细保留"],
   "FILTER 只决定哪些行贡献给 SUM，不删除输出行。只累加 value>=20 时，A 每行都显示合格总量 60，B 没有合格行，用 COALESCE 显示 0。把条件放 WHERE 则会丢掉低值观测。",
   "SELECT id,coalesce(sum(value) FILTER(WHERE value>=20) OVER(PARTITION BY sensor),0) FROM reading ORDER BY id;","1|60\n2|60\n3|60\n4|60\n5|0\n6|0",
   ["FILTER 不能随意应用于所有内置非聚合窗口函数。","空贡献集合的 SUM 为 NULL，而不是零。"],
   ("每行附加同传感器合格观测数量。","COUNT(*) FILTER。","SELECT id,count(*) FILTER(WHERE value>=20) OVER(PARTITION BY sensor) FROM reading ORDER BY id;","1|2\n2|2\n3|2\n4|2\n5|0\n6|0"),
   ("保留 A 全部行，只累计截至当前行的合格值。","有序窗口加 FILTER。","SELECT id,coalesce(sum(value) FILTER(WHERE value>=20) OVER(ORDER BY id ROWS UNBOUNDED PRECEDING),0) FROM reading WHERE sensor='A' ORDER BY id;","1|0\n2|0\n3|20\n4|60")),
 T(252,"named-window-reuse","命名窗口共享分区并派生排序帧",["WINDOW","窗口链","复用"],
   "命名 w 保存 sensor 分区，AVG(w) 计算分区基线，派生窗口 w ORDER BY id 计算累计值。A 平均 20，B 平均 10；明细偏差与累计额能在同一 SELECT 展示。窗口定义复用减少多处排序条件不一致。",
   "SELECT id,value-avg(value) OVER w,sum(value) OVER(w ORDER BY id ROWS UNBOUNDED PRECEDING) FROM reading WINDOW w AS(PARTITION BY sensor) ORDER BY id;","1|-10.0|10\n2|-10.0|20\n3|0.0|40\n4|20.0|80\n5|-5.0|5\n6|5.0|20",
   ["派生窗口不能覆盖基础窗口已定义的同类子句。","基础窗口包含帧时会限制窗口链用法。"],
   ("共享分区分别输出最小值与最大值。","两个聚合使用同一 w。","SELECT id,min(value) OVER w,max(value) OVER w FROM reading WINDOW w AS(PARTITION BY sensor) ORDER BY id;","1|10|40\n2|10|40\n3|10|40\n4|10|40\n5|5|15\n6|5|15"),
   ("每行显示同传感器观测数量。","COUNT(*) OVER w。","SELECT id,count(*) OVER w FROM reading WINDOW w AS(PARTITION BY sensor) ORDER BY id;","1|4\n2|4\n3|4\n4|4\n5|2\n6|2")),
 T(253,"resettable-running-total","遇重置信号重新累计读数",["重置分段","两层窗口","累计"],
   "先对 reset 标记累计得到段号，再按 sensor、段号重新累计 value。A 的前三笔为 10、20、40，第 4 笔 reset 后从 40 开始；B 为 5、20。不能在单层直接嵌套 SUM 窗口，需要 CTE 分开处理。",
   "WITH g AS(SELECT *,sum(reset) OVER(PARTITION BY sensor ORDER BY id ROWS UNBOUNDED PRECEDING) grp FROM reading) SELECT id,sum(value) OVER(PARTITION BY sensor,grp ORDER BY id ROWS UNBOUNDED PRECEDING) FROM g ORDER BY id;","1|10\n2|20\n3|40\n4|40\n5|5\n6|20",
   ["reset 应规范为 0/1，否则段号含义会漂移。","先过滤重置行会破坏分段。"],
   ("输出各传感器各重置段合计。","先分段再 GROUP BY。","WITH g AS(SELECT *,sum(reset) OVER(PARTITION BY sensor ORDER BY id ROWS UNBOUNDED PRECEDING) grp FROM reading) SELECT sensor,grp,sum(value) FROM g GROUP BY sensor,grp ORDER BY sensor,grp;","A|1|40\nA|2|40\nB|1|20"),
   ("列出重置事件的 id。","reset=1。","SELECT id FROM reading WHERE reset=1 ORDER BY id;","1\n4\n5")),
 T(254,"weighted-moving-average","移动加权平均使用两个窗口和",["加权平均","移动帧","NULLIF"],
   "当前与前一行的 value×weight 之和除以 weight 之和，计算移动加权均值。A 的第三笔为 (10×2+20)/3=13.33，B 第二笔为 (5+15×3)/4=12.5。不能把每行均值直接平均，分母权重必须同步移动。",
   "SELECT id,round(1.0*sum(value*weight) OVER w/nullif(sum(weight) OVER w,0),2) FROM reading WINDOW w AS(PARTITION BY sensor ORDER BY id ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) ORDER BY id;","1|10.0\n2|10.0\n3|13.33\n4|30.0\n5|5.0\n6|12.5",
   ["权重总和为零时应返回未知或业务定义值。","负权重通常不属于普通加权平均模型。"],
   ("求每个传感器全分区加权平均。","分组后两个总和相除。","SELECT sensor,round(1.0*sum(value*weight)/sum(weight),2) FROM reading GROUP BY sensor ORDER BY sensor;","A|18.0\nB|12.5"),
   ("求 A 的普通平均作为对照。","普通 AVG 不使用 weight。","SELECT avg(value) FROM reading WHERE sensor='A';","20.0")),
 T(255,"cumulative-distribution-peers","累计分布包含全部并列观测",["CUME_DIST","经验分布","并列"],
   "CUME_DIST 表示小于等于当前值的行数占分区总数。A 两个 10 都为 2/4=0.5，20 为 0.75，40 为 1。它表达经验分布百分位位置，与 ROW_NUMBER 产生的唯一序号不同。",
   "SELECT id,round(cume_dist() OVER(PARTITION BY sensor ORDER BY value),2) FROM reading ORDER BY id;","1|0.5\n2|0.5\n3|0.75\n4|1.0\n5|0.5\n6|1.0",
   ["并列值的 CUME_DIST 相同，并包含整组。","给窗口加唯一 id 会改变并列分布。"],
   ("从 A 选出累计分布超过 0.5 的观测 id。","外层筛选窗口结果。","WITH r AS(SELECT id,cume_dist() OVER(ORDER BY value) cd FROM reading WHERE sensor='A') SELECT id FROM r WHERE cd>0.5 ORDER BY id;","3\n4"),
   ("核对 A 小于等于 10 的比例。","条件计数除总数。","SELECT 1.0*sum(value<=10)/count(*) FROM reading WHERE sensor='A';","0.5")),
 T(256,"percent-rank-vs-cdf","百分等级与累计分布的分母差异",["PERCENT_RANK","RANK","统计口径"],
   "PERCENT_RANK=(RANK-1)/(N-1)，A 两个 10 为 0，20 为 2/3，40 为 1。它与 CUME_DIST 的 <=当前值计数/N 不同，尤其首组有并列时。明确使用哪个统计口径，避免给用户同名却不同值的百分位。",
   "SELECT id,round(percent_rank() OVER(PARTITION BY sensor ORDER BY value),4) FROM reading ORDER BY id;","1|0.0\n2|0.0\n3|0.6667\n4|1.0\n5|0.0\n6|1.0",
   ["单行分区百分等级为 0，而累计分布为 1。","统计百分位位置不等于连续分位值插值。"],
   ("比较单行分区两种分布函数。","先限制为单行。","SELECT percent_rank() OVER(ORDER BY value),cume_dist() OVER(ORDER BY value) FROM reading WHERE id=1;","0.0|1.0"),
   ("返回 A 中百分等级为零的观测 id。","排名后外层过滤。","WITH r AS(SELECT id,percent_rank() OVER(ORDER BY value) p FROM reading WHERE sensor='A') SELECT id FROM r WHERE p=0 ORDER BY id;","1\n2")),
 T(257,"median-with-ranking","不依赖扩展函数计算每组中位数",["中位数","ROW_NUMBER","中心位置"],
   "分别计算行号与分区行数，保留 (N+1)/2 和 (N+2)/2 两个整数中心位置，再 AVG。偶数组 A 的中间值 10、20，中位数 15；B 的 5、15 中位数 10。奇数组两个位置相同，只保留一行。",
   "WITH r AS(SELECT *,row_number() OVER(PARTITION BY sensor ORDER BY value,id) rn,count(*) OVER(PARTITION BY sensor) n FROM reading) SELECT sensor,avg(value) FROM r WHERE rn IN((n+1)/2,(n+2)/2) GROUP BY sensor ORDER BY sensor;","A|15.0\nB|10.0",
   ["排序应明确 NULL 是否排除。","AVG 会输出浮点，金额中位数可能需额外精度政策。"],
   ("求 A 前三笔观测的中位数。","排序后的中心为第二行。","WITH r AS(SELECT value,row_number() OVER(ORDER BY value,id) rn,count(*) OVER() n FROM reading WHERE sensor='A' AND id<=3) SELECT avg(value) FROM r WHERE rn IN((n+1)/2,(n+2)/2);","10.0"),
   ("列出 A 偶数中位数的两个中心值。","四行取行号 2、3。","WITH r AS(SELECT value,row_number() OVER(ORDER BY value,id) rn FROM reading WHERE sensor='A') SELECT value FROM r WHERE rn IN(2,3) ORDER BY rn;","10\n20")),
 T(258,"running-distinct-with-flags","用首现标记计算累计不同值数量",["累计去重","首现标记","窗口限制"],
   "SQLite 不支持 COUNT(DISTINCT) 作为窗口函数。先为 sensor、value 内按 id 编号，首现记 1，再按 sensor 累加首现标记。A 累计不同值为 1、1、2、3，B 为 1、2；重复值只在首次贡献。",
   "WITH first AS(SELECT *,row_number() OVER(PARTITION BY sensor,value ORDER BY id)=1 flag FROM reading) SELECT id,sum(flag) OVER(PARTITION BY sensor ORDER BY id ROWS UNBOUNDED PRECEDING) FROM first ORDER BY id;","1|1\n2|1\n3|2\n4|3\n5|1\n6|2",
   ["此法适用于从起点累计，不直接适用于滑动去重窗口。","NULL 是否作为一种值计入需先定义。"],
   ("按传感器核对最终不同值数量。","普通分组 COUNT DISTINCT。","SELECT sensor,count(DISTINCT value) FROM reading GROUP BY sensor ORDER BY sensor;","A|3\nB|2"),
   ("列出重复值的后续出现 id。","同值分区行号大于一。","WITH r AS(SELECT id,row_number() OVER(PARTITION BY sensor,value ORDER BY id) rn FROM reading) SELECT id FROM r WHERE rn>1 ORDER BY id;","2")),
 T(259,"forward-fill-null-groups","分段窗口向前填充缺失观测",["前值填充","COUNT 分段","缺失数据"],
   "累计 COUNT(v) 只在非空处递增，于是每个非空值和后续空值形成一组；组内 MAX(v) 取到唯一非空值。开头没有已知值仍显示 unset，之后依次 red、red、blue、blue。填充是展示推导，原始 NULL 保持不变。",
   "WITH g AS(SELECT *,count(v) OVER(ORDER BY t ROWS UNBOUNDED PRECEDING) grp FROM observation) SELECT t,coalesce(max(v) OVER(PARTITION BY grp),'unset') FROM g ORDER BY t;","1|unset\n2|red\n3|red\n4|blue\n5|blue",
   ["MAX(v) 只在每段唯一非空值时才代表前值。","填充值不应伪装成真实观测，必要时显示来源。"],
   ("统计原始缺失观测数。","填充查询不会修改表。","SELECT count(*) FROM observation WHERE v IS NULL;","3"),
   ("为每个时点找最近一个非空来源时点。","MAX(CASE) 累计窗口。","SELECT t,max(CASE WHEN v IS NOT NULL THEN t END) OVER(ORDER BY t ROWS UNBOUNDED PRECEDING) FROM observation ORDER BY t;","1|\n2|2\n3|2\n4|4\n5|4")),
 T(260,"value-run-length","检测连续相同值的运行长度",["连续值段","LAG","分段聚合"],
   "先用 LAG 判断相邻 value 是否改变，再累计变化标记生成段号。A 的连续 10 有两行，随后 20、40 各一行，B 的 5、15 各一行。按 value 直接 GROUP BY 会把不相邻的重复值错误合并。",
   "WITH r AS(SELECT *,value IS NOT lag(value) OVER(PARTITION BY sensor ORDER BY id) flag FROM reading),g AS(SELECT *,sum(flag) OVER(PARTITION BY sensor ORDER BY id ROWS UNBOUNDED PRECEDING) grp FROM r) SELECT sensor,min(id),value,count(*) FROM g GROUP BY sensor,grp ORDER BY sensor,min(id);","A|1|10|2\nA|3|20|1\nA|4|40|1\nB|5|5|1\nB|6|15|1",
   ["直接按值分组不能表达相邻连续性。","可空读数使用 IS NOT 才能处理 NULL 变化。"],
   ("列出 A 发生值变化的起始 id。","第一行也视为段起始。","WITH r AS(SELECT id,value IS NOT lag(value) OVER(ORDER BY id) changed FROM reading WHERE sensor='A') SELECT id FROM r WHERE changed ORDER BY id;","1\n3\n4"),
   ("计算 A 最长连续相等观测长度。","累计变化段后取最大行数。","WITH r AS(SELECT *,value IS NOT lag(value) OVER(ORDER BY id) f FROM reading WHERE sensor='A'),g AS(SELECT *,sum(f) OVER(ORDER BY id ROWS UNBOUNDED PRECEDING) k FROM r) SELECT max(n) FROM(SELECT count(*) n FROM g GROUP BY k);","2")),
 T(261,"backfill-next-known","用前向帧定位下一已知观测",["后值填充","FOLLOWING","来源关联"],
   "在当前行至末行的前向帧中，MIN(非空时点) 找到下一已知来源，再连接回原表取值。时点 1、2 得 red，3、4 得 blue，5 后无已知值保持 unset。该方法不声称 SQLite 支持 IGNORE NULLS。",
   "WITH r AS(SELECT t,min(CASE WHEN v IS NOT NULL THEN t END) OVER(ORDER BY t ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) source FROM observation) SELECT r.t,coalesce(o.v,'unset') FROM r LEFT JOIN observation o ON o.t=r.source ORDER BY r.t;","1|red\n2|red\n3|blue\n4|blue\n5|unset",
   ["后值填充使用了未来信息，不适合无泄漏实时预测。","没有下一来源时必须保留未知状态。"],
   ("列出无下一已知观测的时点。","前向 MIN 结果为空。","WITH r AS(SELECT t,min(CASE WHEN v IS NOT NULL THEN t END) OVER(ORDER BY t ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) n FROM observation) SELECT t FROM r WHERE n IS NULL ORDER BY t;","5"),
   ("输出下一个已知来源时点。","展示推导值的来源。","SELECT t,min(CASE WHEN v IS NOT NULL THEN t END) OVER(ORDER BY t ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) FROM observation ORDER BY t;","1|2\n2|2\n3|4\n4|4\n5|")),
]
